    font-weight: bold;
    display: inline-block;
    margin-top: 1rem;
    border-bottom: 1px solid transparent;
}

.text-link:hover {
    border-bottom-color: var(--accent-color);
}

/* Editorial */
.editorial-content {
    background-color: var(--surface-color);
    padding: var(--spacing-md);
