    --bg-color: #121212;
    --surface-color: #1e1e1e;
    --primary-text: #ffffff;
    --secondary-text: #b0b0b0;
    --accent-color: #d4af37; /* Gold */
    --accent-hover: #f1c40f;
    --border-color: #333;
    --button-bg: #ffffff;
    --button-text: #121212;
    --container-width: 1200px;
    --spacing-lg: 4rem;
    --spacing-md: 2rem;
    --spacing-sm: 1rem;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--primary-text);
    line-height: 1.6;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 var(--spacing-sm);
}

/* Accessibility: Focus styles */
:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Accessibility: Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: black;
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Header & Nav */
header {
    background-color: rgba(18, 18, 18, 0.95);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 50;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: var(--container-width);
    margin: 0 auto;
    padding: var(--spacing-sm);
}

.logo {
    font-size: 1.5rem;
    font-weight: bold;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    color: var(--primary-text);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s;
}

.nav-links a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    gap: 1rem;
}

.icon-btn {
    background: none;
    border: none;
    color: var(--primary-text);
    cursor: pointer;
    font-size: 1.2rem;
    position: relative;
}

#cart-count {
    font-size: 0.7rem;
    background: var(--accent-color);
    color: black;
    padding: 2px 6px;
    border-radius: 50%;
    position: absolute;
    top: -5px;
    right: -10px;
}

/* Hero Section */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), 
                url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1600&q=80') no-repeat center/cover;
}

.hero-content h1 {
    font-size: clamp(2.5rem, 8vw, 5rem);
    margin-bottom: var(--spacing-sm);
    text-transform: uppercase;
    letter-spacing: 4px;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--secondary-text);
    margin-bottom: var(--spacing-md);
    max-width: 600px;
    margin-inline: auto;
}

.cta-button {
    display: inline-block;
    background-color: var(--button-bg);
    color: var(--button-text);
    padding: 1rem 2.5rem;
    text-decoration: none;
    font-weight: bold;
    text-transform: uppercase;
    transition: transform 0.3s, background-color 0.3s;
}

.cta-button:hover {
    transform: translateY(-3px);
    background-color: var(--accent-color);
}

/* Sections */
section {
    padding: var(--spacing-lg) 0;
}

h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 2px;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-md);
}

.product-card {
    background-color: var(--surface-color);
    padding: var(--spacing-sm);
    border: 1px solid var(--border-color);
    transition: border-color 0.3s;
}

.product-card:hover {
    border-color: var(--accent-color);
}

.product-image {
    aspect-ratio: 1;
    margin-bottom: var(--spacing-sm);
}

.product-card h3 {
    font-size: 1.2rem;
    margin-bottom: 0.5rem;
}

.price {
    color: var(--accent-color);
    font-weight: bold;
    margin-bottom: var(--spacing-sm);
}

.add-to-cart {
    width: 100%;
    padding: 0.75rem;
    background: transparent;
    border: 1px solid var(--primary-text);
    color: var(--primary-text);
    cursor: pointer;
    font-weight: bold;
    transition: background 0.3s, color 0.3s;
}

.add-to-cart:hover {
    background: var(--primary-text);
    color: var(--bg-color);
}

/* Deals */
.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
}

.deal-item {
    background: var(--surface-color);
    padding: var(--spacing-md);
    text-align: center;
    border: 2px dashed var(--accent-color);
}

.deal-item h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.text-link {
    color: var(--accent-color);
    text-decoration: none;
    font-weight: bold;
    display: inline-block;
    margin-top: 1rem;
    border-bottom: 1px solid transparent;
}

.text-link:hover {
    border-bottom-color: var(--accent-color);
}

/* Editorial */
.editorial-content {
    background-color: var(--surface-color);
    padding: var(--spacing-md);
    max-width: 800px;
    margin: 0 auto;
}

/* Footer */
footer {
    padding: var(--spacing-lg) 0;
    border-top: 1px solid var(--border-color);
    margin-top: var(--spacing-lg);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-md);
}

.footer-grid h4 {
    margin-bottom: var(--spacing-sm);
    text-transform: uppercase;
}

.footer-grid ul {
    list-style: none;
}

.footer-grid a {
    color: var(--secondary-text);
    text-decoration: none;
}

.footer-grid a:hover {
    color: var(--primary-text);
}

.copyright {
    text-align: center;
    color: var(--secondary-text);
    font-size: 0.9rem;
}

/* Mobile Adjustments */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .deals-grid {
        grid-template-columns: 1fr;
    }
    .hero {
        height: 60vh;
    }
}
