}

.product-card:hover {
    border-color: var(--accent-color);
}

.product-image {
    aspect-ratio: 1;
    margin-bottom: var(--spacing-sm);
}

.product-card h3 {
    font-size: 1.2rem;
    margin-bottom: 0.5rem;
}

.price {
    color: var(--accent-color);
    font-weight: bold;
    margin-bottom: var(--spacing-sm);
}

.add-to-cart {
    width: 100%;
