    font-weight: bold;
    transition: background 0.3s, color 0.3s;
}

.add-to-cart:hover {
    background: var(--primary-text);
    color: var(--bg-color);
}

/* Deals */
.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
}

.deal-item {
