    color: var(--primary-text);
}

.copyright {
    text-align: center;
    color: var(--secondary-text);
    font-size: 0.9rem;
}

/* Mobile Adjustments */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .deals-grid {
        grid-template-columns: 1fr;
    }
    .hero {
        height: 60vh;
    }
}
